css:
@import url("s://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap");

:root {
  --bg-color: #f2f2f6;
  --folder-back-color: #469cf4;
  --folder-front-grad-start: #6db6fb;
  --folder-front-grad-end: #3b93ee;
  --paper-color: #ffffff;
  --text-main: #ffffff;
  --text-sub: rgba(255, 255, 255, 0.75);
  --font-sans: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont,
    "Segoe UI", Roboto, sans-serif;
  --font-mono: "JetBrains Mono", SFMono-Regular, Consolas, monospace;
}

.card-viewport {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 28em;
  width: 100%;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
  font-family: var(--font-sans);
  background: transparent;
}

.memo-checkbox {
  display: none;
}

.folder-container {
  position: relative;
  width: 320px;
  height: 270px;
  filter: drop-shadow(0 15px 25px rgba(0, 0, 0, 0.12));
  perspective: 1000px;
  transform-style: preserve-3d;
  transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);
}

.folder-container:hover {
  transform: translateY(-4px) rotateX(4deg);
}

.memo-checkbox:checked ~ .folder-container {
  transform: translateY(-2px) rotateX(2deg);
}

.folder-glow {
  position: absolute;
  top: 25px;
  left: 15px;
  width: 290px;
  height: 220px;
  border-radius: 24px;
  filter: blur(48px);
  pointer-events: none;
  z-index: 0;
  opacity: 0;
  background-color: rgba(56, 166, 253, 0.45);
  transform: scale(0.9);
  transition:
    opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.folder-container:hover .folder-glow {
  opacity: 0.22;
  transform: scale(1.02);
}

.memo-checkbox:checked ~ .folder-container .folder-glow {
  opacity: 0.38;
  transform: scale(1.08);
}

.back-cover {
  position: absolute;
  top: 30px;
  left: 0;
  width: 100%;
  height: 240px;
  background-color: var(--folder-back-color);
  border-radius: 0 18px 18px 18px;
  z-index: 1;
}

.back-tab {
  position: absolute;
  top: 0;
  left: 0;
  width: 130px;
  height: 50px;
  background-color: var(--folder-back-color);
  border-radius: 14px 14px 0 0;
  z-index: 1;
}

.swoop {
  position: absolute;
  top: 14px;
  left: 130px;
  width: 16px;
  height: 16px;
  background: radial-gradient(
    circle at top right,
    transparent 16px,
    var(--folder-back-color) 16.5px
  );
  z-index: 1;
}

.paper {
  position: absolute;
  top: 40px;
  left: 12px;
  right: 12px;
  height: 200px;
  background-color: var(--paper-color);
  background-image: radial-gradient(#e5e7eb 1px, transparent 1px);
  background-size: 8px 8px;
  border-radius: 14px 14px 0 0;
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.04);
  z-index: 2;
  overflow: hidden;
  transition:
    transform 0.5s cubic-bezier(0.25, 1, 0.5, 1),
    opacity 0.4s ease,
    box-shadow 0.4s ease;
}

.memo-checkbox:checked ~ .folder-container .paper {
  transform: translateY(-90px) rotate(-2deg) rotateY(5deg) scale(1.02);
  z-index: 3;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.22);
  transition:
    transform 0.65s cubic-bezier(0.34, 1.8, 0.55, 1) 0.08s,
    box-shadow 0.65s ease 0.08s;
}

.front-cover {
  position: absolute;
  top: 72px;
  left: 0;
  width: 100%;
  height: 198px;
  background: linear-gradient(
    150deg,
    var(--folder-front-grad-start) 0%,
    var(--folder-front-grad-end) 100%
  );
  border-radius: 18px;
  box-shadow:
    inset 1.5px 2px 4px rgba(255, 255, 255, 0.45),
    inset -1px -1px 3px rgba(0, 0, 0, 0.1),
    0 -2px 10px rgba(0, 0, 0, 0.06),
    0 8px 20px rgba(0, 0, 0, 0.1);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-sizing: border-box;
  padding: 22px 24px;
  z-index: 5;
  transform-origin: bottom center;
  transform: perspective(1000px) rotateX(0deg);
  transition:
    transform 0.6s cubic-bezier(0.25, 1, 0.5, 1) 0.12s,
    box-shadow 0.6s cubic-bezier(0.25, 1, 0.5, 1) 0.12s;
  cursor: pointer;
}

.cover-highlight {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.18) 0%,
    rgba(255, 255, 255, 0) 60%
  );
  border-radius: 18px;
  pointer-events: none;
  z-index: 1;
}

.header {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  width: 100%;
}

.title-group {
  display: flex;
  flex-direction: column;
  text-align: left;
}

.cover-main-title {
  color: var(--text-main);
  font-size: 23px;
  font-weight: 700;
  letter-spacing: -0.3px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.cover-subtitle {
  margin-top: 4px;
  color: var(--text-sub);
  font-size: 13.5px;
  font-weight: 400;
  letter-spacing: 0.2px;
}

.icon-group {
  display: flex;
  gap: 14px;
  padding-top: 4px;
}

.icon-group svg {
  width: 20px;
  height: 20px;
  fill: var(--text-main);
  opacity: 0.85;
  transition:
    opacity 0.2s ease,
    transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.folder-container:hover .icon-group svg:last-child {
  transform: rotate(45deg);
  opacity: 1;
}

.footer {
  position: relative;
  z-index: 2;
  text-align: left;
}

.cover-notes-count {
  color: rgba(255, 255, 255, 0.95);
  font-size: 14.5px;
  font-weight: 500;
}

.folder-container:hover .front-cover {
  transform: perspective(1000px) rotateX(-12deg);
  transition-delay: 0s;
}

.memo-checkbox:checked ~ .folder-container .front-cover {
  transform: perspective(1000px) rotateX(-28deg);
  box-shadow:
    inset 1.5px 2px 4px rgba(255, 255, 255, 0.45),
    inset -1px -1px 3px rgba(0, 0, 0, 0.1),
    0 -2px 10px rgba(0, 0, 0, 0.04),
    0 16px 36px rgba(10, 115, 219, 0.26);
  transition:
    transform 0.6s cubic-bezier(0.2, 1.35, 0.4, 1) 0s,
    box-shadow 0.6s cubic-bezier(0.2, 1.35, 0.4, 1) 0s;
}

.memo-header {
  background-color: #ffd043;
  height: 34px;
  padding: 0 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1.5px dashed rgba(94, 72, 0, 0.22);
  box-sizing: border-box;
}

.memo-date {
  font-size: 7.5px;
  color: #5e4800;
  font-weight: 600;
  display: flex;
  align-items: center;
}

.time-badge {
  background-color: rgba(255, 255, 255, 0.4);
  color: #5e4800;
  border-radius: 8px;
  padding: 1px 5px;
  font-weight: 700;
  margin-left: 5px;
  display: inline-block;
}

.memo-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-dots-icon {
  width: 10px;
  height: 10px;
  color: #5e4800;
  opacity: 0.7;
}

.memo-done-btn {
  font-size: 7.5px;
  color: #5e4800;
  background: rgba(255, 255, 255, 0.35);
  border-radius: 10px;
  padding: 2.5px 8px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background-color 0.2s ease,
    transform 0.1s ease;
}

.memo-done-btn:hover {
  background: rgba(255, 255, 255, 0.65);
}

.memo-done-btn:active {
  transform: scale(0.95);
}

.memo-body {
  padding: 12px 10px;
  display: flex;
  flex-direction: column;
  height: calc(100% - 34px);
  box-sizing: border-box;
  position: relative;
  background-color: #ffffff;
  counter-reset: todo-total 0 todo-done 0;
}

.memo-body::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 28px;
  width: 1px;
  background-color: rgba(239, 68, 68, 0.3);
  z-index: 1;
  pointer-events: none;
}

.memo-title {
  order: -2;
  font-size: 11px;
  font-weight: 700;
  color: #1f2937;
  margin-top: 4px;
  margin-bottom: 8px;
  display: block;
  text-align: left;
}

.memo-title::after {
  content: " (" counter(todo-done) "/" counter(todo-total) ")";
  font-size: 9px;
  font-weight: 500;
  color: #6b7280;
  margin-left: 4px;
}

.todo-list {
  order: -1;
  display: flex;
  flex-direction: column;
  gap: 0;
  flex-grow: 1;
  overflow-y: auto;
  background: linear-gradient(rgba(0, 0, 0, 0) 96%, #e5e7eb 96%);
  background-size: 100% 22px;
  padding-left: 28px;
  box-sizing: border-box;
}

.todo-item {
  counter-increment: todo-total;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 9px;
  color: #374151;
  cursor: pointer;
  height: 22px;
  box-sizing: border-box;
  position: relative;
  z-index: 2;
}

.todo-text {
  position: relative;
  transition: color 0.3s ease;
  font-family: var(--font-sans);
}

.todo-text::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  width: 0;
  height: 1px;
  background-color: #9ca3af;
  transition: width 0.3s ease-in-out;
}

.todo-checkbox:checked ~ .todo-text::before {
  width: 100%;
}

.todo-checkbox:checked ~ .todo-text {
  color: #9ca3af;
}

.todo-checkbox {
  appearance: none;
  -webkit-appearance: none;
  width: 11px;
  height: 11px;
  border: 1px solid #f59e0b;
  border-radius: 50%;
  outline: none;
  cursor: pointer;
  position: relative;
  background-color: #fff;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.todo-checkbox:checked {
  background-color: #f59e0b;
  border-color: #f59e0b;
  counter-increment: todo-done;
}

.todo-checkbox::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 3.5px;
  width: 2.5px;
  height: 4.5px;
  border: solid white;
  border-width: 0 1.2px 1.2px 0;
  transform: rotate(45deg) scale(0);
  transition: transform 0.15s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.todo-checkbox:checked::after {
  transform: rotate(45deg) scale(1);
}

.memo-footer {
  border-top: 1px solid #f3f4f6;
  padding-top: 6px;
  margin-top: 6px;
}

.footer-txt {
  font-size: 7.5px;
  color: #4b5563;
  display: block;
  text-align: center;
}

.hashtag {
  color: #db2777;
  background-color: #fce7f3;
  padding: 1.5px 5.5px;
  border-radius: 4px;
  font-weight: 700;
  display: inline-block;
}
